function CODE3(p, q, r, s):            // four distinct backbone positions
    if max(p,q) < min(r,s) or max(r,s) < min(p,q): return 0     // pairing pq|rs
    if max(p,r) < min(q,s) or max(q,s) < min(p,r): return 1     // pairing pr|qs
    return 2                                                    // pairing ps|qr

function SIGNATURE(order, n):
    W <- empty list
    for each (a<b<c<d) in lexicographic order over subsets of {0..n-1} of size 4:
        append CODE3(order[a], order[b], order[c], order[d]) to W
    return W                                        // a word of length C(n,4)

function CONSTANT_COORDINATES(orders[1..k], n):
    S[i] <- SIGNATURE(orders[i], n) for i = 1..k
    C <- empty list
    for j = 1 to C(n,4):
        if S[1][j] = S[2][j] = ... = S[k][j]: append the j-th four-set to C
    return C                       // the common quartets of the family

function AVOIDS_COMMON_QUARTET(orders, n):
    return CONSTANT_COORDINATES(orders, n) is empty

function SHARES_WITH_IDENTITY(u, n):
    id <- (0, 1, ..., n-1)
    for each four-set (a<b<c<d) of {0..n-1}:
        if CODE3(id[a],id[b],id[c],id[d]) = CODE3(u[a],u[b],u[c],u[d]):
            return (a,b,c,d)                 // a common quartet
    return NONE

function PAIR_THRESHOLD_HOLDS(n):
    // by equivariance q_pi(sigma x) = q_{pi sigma}(x), the pair (pi,rho)
    // shares a quartet iff (id, rho o pi^{-1}) does
    for each permutation u of {0..n-1}:            // n! candidates, not (n!)^2
        if SHARES_WITH_IDENTITY(u, n) = NONE: return FALSE
    return TRUE

// n = 5 returns FALSE with witness (0,3,2,1,4); n = 6 returns TRUE, so h(2) = 6

